const express = require('express');
const { Pool } = require('pg');

const router = express.Router();
const pool = new Pool(); // reads PG* env vars

const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

const encodeCursor = (row) =>
  Buffer.from(JSON.stringify([row.cursor_ts, row.id])).toString('base64url');

function decodeCursor(cursor) {
  try {
    const [ts, id] = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
    if (typeof ts !== 'string' || !/^\d+$/.test(String(id))) return null;
    return [ts, String(id)];
  } catch {
    return null;
  }
}

router.get('/orders', async (req, res, next) => {
  const limit = req.query.limit === undefined ? DEFAULT_LIMIT : Number(req.query.limit);
  if (!Number.isInteger(limit) || limit < 1 || limit > MAX_LIMIT) {
    return res.status(400).json({ error: `limit must be an integer 1-${MAX_LIMIT}` });
  }

  let after = null;
  if (req.query.cursor !== undefined) {
    after = decodeCursor(String(req.query.cursor));
    if (!after) return res.status(400).json({ error: 'invalid cursor' });
  }

  try {
    // Fetch limit + 1 to detect a next page without a COUNT.
    const { rows } = await pool.query(
      `SELECT o.*, o.created_at::text AS cursor_ts
         FROM orders o
        WHERE $1::timestamptz IS NULL
           OR (o.created_at, o.id) < ($1::timestamptz, $2::bigint)
        ORDER BY o.created_at DESC, o.id DESC
        LIMIT $3`,
      [after ? after[0] : null, after ? after[1] : null, limit + 1]
    );

    const hasMore = rows.length > limit;
    const page = hasMore ? rows.slice(0, limit) : rows;
    const nextCursor = hasMore ? encodeCursor(page[page.length - 1]) : null;

    res.json({
      data: page.map(({ cursor_ts, ...order }) => order),
      next_cursor: nextCursor,
      has_more: hasMore,
    });
  } catch (err) {
    // Malformed timestamp or id inside a tampered cursor.
    if (['22007', '22008', '22P02', '22003'].includes(err.code)) {
      return res.status(400).json({ error: 'invalid cursor' });
    }
    next(err);
  }
});

module.exports = router;
